{
  bool     got;
  bool     pr     = false;
  uint16_t tx     = 0;
  uint16_t ty     = 0;

  nxmutex_lock(&g_touch_lock);

  /* 镜像没在跑就一定不给：这是"跟镜像走"的开关，也是最后一道保险 ——
   * 停止/断开时触摸已经被清成抬起，这里再挡一次，界面永远不会卡在按下。 */
  got = g_running && g_touch_ever;
  if (got)
    {
      tx = g_touch_x;
      ty = g_touch_y;

      if (g_touch_latch)
        {
          /* "按下"还没被看见过：先补一次，下一次读才给真实状态。
           * 鼠标快速点一下（按下和抬起落在同一个读取周期里）靠这个不丢。 */
          g_touch_latch = false;
          pr = true;
        }
      else
        {
          pr = g_touch_pressed;
        }
    }

  nxmutex_unlock(&g_touch_lock);

  if (got)
    {
      if (x != NULL)
        {
          *x = tx;
        }

      if (y != NULL)
        {
          *y = ty;
        }

      if (pressed != NULL)
        {
          *pressed = pr;
        }
    }

  return got;
}

