 * 每次重建清单都会调一次，所以这里每次都返回一份新的堆内存（框架负责 free）。
 * 清单是编译期常量，不用加锁。
 *
 * @return malloc 出来的 JSON 数组字符串；NULL 表示这次没有工具
 */

static char *ai_tools_provider_get_tools(void)
{
  size_t len = strlen(AI_TOOLS_JSON_ARRAY) + 1;
  char *out = malloc(len);

  if (out == NULL)
    {
      return NULL;
    }

  memcpy(out, AI_TOOLS_JSON_ARRAY, len);
  return out;
}

