# Re-enable ICS (Internet Connection Sharing): public = Wi-Fi, private = the board's RNDIS NIC.
# ASCII only on purpose (PowerShell 5.1 reads BOM-less .ps1 as ANSI).
# Run elevated: powershell -NoProfile -ExecutionPolicy Bypass -File ics_share.ps1

$log = 'C:\Windows\Temp\ics_share.log'
Remove-Item $log -ErrorAction SilentlyContinue
function Say($m) { Write-Output $m; Add-Content -Path $log -Value $m -Encoding utf8 }

$hnet = New-Object -ComObject HNetCfg.HNetShare

$pub = $null
$priv = $null
foreach ($c in $hnet.EnumEveryConnection) {
    $p = $hnet.NetConnectionProps($c)
    Say ('conn name="' + $p.Name + '" dev="' + $p.DeviceName + '" status=' + $p.Status)
    if ($p.DeviceName -like '*Wi-Fi*' -or $p.DeviceName -like '*Wireless*' -or $p.Name -eq 'WLAN') { if (-not $pub) { $pub = $c } }
    if ($p.DeviceName -like '*Remote NDIS*' -or $p.DeviceName -like '*NDIS*') { if (-not $priv) { $priv = $c } }
}

if (-not $pub)  { Say 'PUBLIC (wifi) not found'; exit 1 }
if (-not $priv) { Say 'PRIVATE (rndis) not found'; exit 1 }

Say ('public  = ' + $hnet.NetConnectionProps($pub).Name)
Say ('private = ' + $hnet.NetConnectionProps($priv).Name)

try {
    $c1 = $hnet.INetSharingConfigurationForINetConnection($pub)
    if ($c1.SharingEnabled) { Say 'public already sharing; disable first'; $c1.DisableSharing(); Start-Sleep 2 }
    $c1.EnableSharing(0)
    Say 'public sharing enabled'
} catch { Say ('public enable failed: ' + $_.Exception.Message) }

try {
    $c2 = $hnet.INetSharingConfigurationForINetConnection($priv)
    if ($c2.SharingEnabled) { Say 'private already sharing; disable first'; $c2.DisableSharing(); Start-Sleep 2 }
    $c2.EnableSharing(1)
    Say 'private sharing enabled'
} catch { Say ('private enable failed: ' + $_.Exception.Message) }

Start-Sleep -Seconds 15
